      "id": "resonanceSweep",
      "type": "animation",
      "label": "Sweep the field and build the spectrum",
      "loop": false,
      "teaches": "Sweeping B₀ continuously traces out the whole spectrum: each absorption event the sample undergoes becomes one peak on the plotted line."
    },
    {
      "id": "orbitView",
      "type": "orbit",
      "teaches": "The coil axis is perpendicular to the S–N field axis, and the sample sits exactly at the center of the magnet gap inside the coil."
    }
  ],
  "demo_steps": [
    {
      "title": "The instrument at rest",
      "narration": "A glass tube of sample stands in the gap between the S and N pole pieces, wrapped by the green rf coil. Green leads feed rf energy in from the generator; blue cables carry the response out to the detector and on to the monitor.",
      "state": { "fieldStrength": 2.1 }
    },
    {
      "title": "Follow the signal path",
      "narration": "Clicking the generator, then the coil, then the detector, then the monitor lights each stage and its cables in turn — rf irradiation goes in, the sample's absorption comes back out, and the amplified signal is drawn as a line.",
      "state": { "fieldStrength": 2.1 }
    },
    {
      "title": "Below resonance",
      "narration": "With the rf frequency held constant at 9.56, a low field leaves every nucleus off resonance: the spins stay aligned, the sample is dark, and the monitor baseline is flat.",
      "state": { "fieldStrength": 1.85 }
    },
    {
      "title": "First nucleus in resonance",
      "narration": "Raising the field brings the most deshielded protons to the point where their spin-flip energy matches the rf photon. Those spins flash and flip, and the corresponding peak appears at the left of the trace.",
      "state": { "fieldStrength": 2.02 }
