base.scale.z = 0.5; base.position.set(0, -2.22, 0); monitor.add(base);

// spectrum screen
const SPW = 560, SPH = 356;
const spec = mkCanvas(SPW, SPH);
const specTex = texFrom(spec.cv);
const screen = new THREE.Mesh(new THREE.PlaneGeometry(4.1, 2.6),
  new THREE.MeshBasicMaterial({ map: specTex }));
screen.position.set(0, 0.06, 0.16); monitor.add(screen);

const peaks = [
  { B: 2.02, I: 0.35 }, { B: 2.06, I: 0.55 }, { B: 2.10, I: 0.30 },
  { B: 2.38, I: 1.00 }, { B: 2.44, I: 0.75 }
];
const amp = peaks.map(() => 0);
let B0 = 2.1, B0target = 2.1;

function specX(b) { return 44 + ((b - 1.8) / 0.8) * (SPW - 88); }
function drawSpectrum() {
  const ctx = spec.ctx;
  ctx.fillStyle = '#A8D8EF'; ctx.fillRect(0, 0, SPW, SPH);
  const baseY = SPH - 0.35 * SPH, top = 28, head = baseY - top;
  // cursor
  ctx.strokeStyle = 'rgba(20,50,90,0.35)'; ctx.lineWidth = 2;
  ctx.setLineDash([6, 6]); ctx.beginPath();
  ctx.moveTo(specX(B0), top - 14); ctx.lineTo(specX(B0), baseY + 20); ctx.stroke();
  ctx.setLineDash([]);
  // peaks
  peaks.forEach((p, i) => {
    const x = specX(p.B), h = head * p.I * amp[i];
    if (h < 0.5) return;
    const on = Math.abs(B0 - p.B) < 0.02;
    if (on) { ctx.shadowColor = '#ff5a30'; ctx.shadowBlur = 16; }
    ctx.strokeStyle = on ? '#FF3A18' : '#1d1010';
    ctx.lineWidth = on ? 5 : 3;
    ctx.beginPath(); ctx.moveTo(x, baseY); ctx.lineTo(x, baseY - h); ctx.stroke();
    ctx.shadowBlur = 0;
  });
  // baseline
  ctx.strokeStyle = '#D93A2B'; ctx.lineWidth = 5;
  ctx.beginPath(); ctx.moveTo(14, baseY); ctx.lineTo(SPW - 14, baseY); ctx.stroke();
  ctx.fillStyle = 'rgba(20,50,90,0.55)'; ctx.font = '17px sans-serif';
  ctx.textAlign = 'left'; ctx.fillText('B₀ →', 18, SPH - 14);
  ctx.textAlign = 'right'; ctx.fillText(B0.toFixed(3) + ' T', SPW - 18, SPH - 14);
  specTex.needsUpdate = true;
}
drawSpectrum();

/* ── CABLES ─────────────────────────────────────────────────────────────── */
const cables = [];
function makeCable(p0, c1, c2, p3, color, off) {
  const curve = new THREE.CubicBezierCurve3(
    p0.clone().add(off), c1.clone().add(off), c2.clone().add(off), p3.clone().add(off));
  const mat = new THREE.MeshStandardMaterial({
    color, roughness: 0.45, metalness: 0.1, emissive: new THREE.Color(0x000000)
  });
  const mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 90, 0.05, 8, false), mat);
  scene.add(mesh);
  const rec = { curve, mesh, mat, baseColor: color };
  cables.push(rec);
  return rec;
}
const cableSets = { green: [], blueIn: [], blueOut: [] };
[[0, 0.07, 0.05], [0, -0.07, -0.05]].forEach(o => {
  const off = new THREE.Vector3(o[0], o[1], o[2]);
  cableSets.green.push(makeCable(
    new THREE.Vector3(-4.25, -2.45, 1.45), new THREE.Vector3(-3.0, -2.30, 1.10),
    new THREE.Vector3(-1.7, -2.55, 0.35), new THREE.Vector3(-0.55, -1.95, 0.10),
    0x3FA845, off));
  cableSets.blueIn.push(makeCable(
    new THREE.Vector3(0.52, -1.95, 0.12), new THREE.Vector3(1.7, -2.25, 0.70),
    new THREE.Vector3(3.0, -2.70, 1.35), new THREE.Vector3(3.95, -2.45, 1.45),
    0x2AA8E0, off));
  cableSets.blueOut.push(makeCable(
