/* ── DIM / FOCUS SYSTEM ─────────────────────────────────────────────────── */
const dimSets = {};
['coilAssembly', 'magnets', 'generator', 'detector', 'monitor'].forEach(name => {
  const recs = [];
  G[name].traverse(o => {
    if (!o.isMesh) return;
    o.material = o.material.clone();
    recs.push({ m: o.material, op: o.material.opacity, tr: o.material.transparent, dw: o.material.depthWrite });
  });
  dimSets[name] = recs;
});
let focusStage = null;
function setFocus(stage) {
  focusStage = stage;
  Object.keys(dimSets).forEach(k => {
    const dim = stage && k !== stage && !(stage === 'coilAssembly' && k === 'magnets');
    dimSets[k].forEach(r => {
      r.m.transparent = dim ? true : r.tr;
      r.m.opacity = dim ? r.op * 0.35 : r.op;
      r.m.depthWrite = dim ? false : r.dw;
      if (r.m.emissive) r.m.emissive.setHex(!dim && stage && k === stage ? 0x1d3350 : 0x000000);
    });
  });
  cables.forEach(c => {
    c.mat.transparent = !!stage; c.mat.opacity = stage ? 0.75 : 1;
    c.mat.emissive.setHex(stage ? 0x224422 : 0x000000);
  });
  pulses.forEach(p => { p.mesh.visible = !!stage; });
  document.querySelectorAll('.pathBtn').forEach(b =>
    b.classList.toggle('active', b.dataset.stage === stage));
}

