/* ── DEMO STEPS ─────────────────────────────────────────────────────────── */
const steps = [
  { t: 'The instrument at rest', n: 'A glass tube of sample stands in the gap between the S and N pole pieces, wrapped by the green rf coil. Green leads feed rf energy in from the generator; blue cables carry the response out to the detector and on to the monitor.', B: 2.1, path: false },
  { t: 'Follow the signal path', n: 'Generator → coil + sample → detector/amplifier → monitor. Each stage lights in turn: rf irradiation goes in, the sample\'s absorption comes back out through the same coil, and the amplified signal is drawn as a line.', B: 2.1, path: true },
  { t: 'Below resonance', n: 'With the rf frequency held at 9.56, a low field leaves every nucleus off resonance: the spins stay aligned with B₀ and the monitor baseline is flat.', B: 1.85, path: false },
  { t: 'First nucleus in resonance', n: 'Raising the field brings the most deshielded protons to the point where their spin-flip energy matches the rf photon. Those spins flash and flip, and a peak appears at the left of the trace.', B: 2.02, path: false },
  { t: 'Shielded nuclei resonate later', n: 'More shielded nuclei need a slightly stronger field, because their local electrons oppose B₀. They resonate separately and add their own peak further right — chemically distinct nuclei give distinct signals.', B: 2.38, path: false },
  { t: 'Full sweep', n: 'Sweeping the field through the whole range visits every resonance in order and builds the complete spectrum shown on the monitor.', B: 2.6, path: false }
];
let stepIdx = 0;
let pathTimers = [];
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.t;
  document.getElementById('stepNarr').textContent = s.n;
  pathTimers.forEach(clearTimeout); pathTimers = [];
  if (stepIdx === 5) { sweeping = true; sweepT = 0; B0 = 1.8; }
  else { sweeping = false; B0target = s.B; }
  slider.value = s.B;
  if (s.path) {
    const order = ['generator', 'coilAssembly', 'detector', 'monitor'];
    order.forEach((st, k) => pathTimers.push(setTimeout(() => setFocus(st), k * 1200)));
  } else setFocus(null);
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
goToStep(0);

/* ── UPDATE LOOP ────────────────────────────────────────────────────────── */
let lastT = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastT) / 1000); lastT = now;

  if (sweeping) {
    sweepT += dt / 11;
    if (sweepT >= 1) { sweepT = 1; sweeping = false; }
    B0 = 1.8 + 0.8 * sweepT; B0target = B0;
    slider.value = B0.toFixed(3);
  } else if (Math.abs(B0 - B0target) > 1e-4) {
    B0 += (B0target - B0) * Math.min(1, dt * 4);
    slider.value = B0.toFixed(3);
  }

  // resonance test
  let resonant = -1;
  peaks.forEach((p, i) => { if (Math.abs(B0 - p.B) < 0.02) resonant = i; });
  if (resonant >= 0) amp[resonant] = Math.min(1, amp[resonant] + dt * 4);

  b0val.textContent = B0.toFixed(3);
  if (resonant >= 0) {
    resStatus.textContent = 'RESONANCE — nucleus ' + (resonant + 1) + ' absorbs (ν = γB₀/2π)';
    resStatus.style.background = '#ffe2c9'; resStatus.style.color = '#a03a00';
  } else {
    resStatus.textContent = 'off resonance — spins stay aligned';
    resStatus.style.background = '#eef1f4'; resStatus.style.color = '#555';
  }

  // spins
  const tgtPhase = resonant >= 0 ? 1 : 0;
  spinPhase += (tgtPhase - spinPhase) * Math.min(1, dt * 9);
  flash += ((resonant >= 0 ? 1 : 0) - flash) * Math.min(1, dt * 8);
  const ang = -Math.PI / 2 + Math.PI * spinPhase;
  spins.forEach((g, i) => { g.rotation.z = ang + 0.06 * Math.sin(now * 0.004 + i); });
  spinMat.emissive.setRGB(flash, flash, flash * 0.9);
  spinMat.color.setRGB(0.17 + 0.8 * flash, 0.25 + 0.72 * flash, 0.56 + 0.4 * flash);

  // field lines opacity with B0
  const fo = 0.12 + 0.55 * ((B0 - 1.8) / 0.8);
  fieldMats.forEach(m => { m.opacity = fo; });

  // pulses
  if (focusStage) {
    pulses.forEach(p => {
      p.t = (p.t + dt * 0.55) % 1;
      p.mesh.position.copy(p.curve.getPoint(p.t));
    });
  }

  drawSpectrum();
}
tick();
